/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `cms_pages` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `preview_token` varchar(64) DEFAULT NULL,
  `category_id` int(10) unsigned DEFAULT NULL,
  `template_id` int(10) unsigned DEFAULT NULL,
  `header_component_id` int(10) unsigned DEFAULT NULL,
  `footer_component_id` int(10) unsigned DEFAULT NULL,
  `custom_css` text DEFAULT NULL,
  `custom_js` text DEFAULT NULL,
  `status` enum('draft','pending','published','archived') NOT NULL DEFAULT 'draft',
  `meta_title` varchar(255) DEFAULT NULL,
  `meta_description` text DEFAULT NULL,
  `meta_keywords` varchar(255) DEFAULT NULL,
  `canonical_url` varchar(500) DEFAULT NULL,
  `og_title` varchar(255) DEFAULT NULL,
  `og_description` text DEFAULT NULL,
  `og_image` varchar(500) DEFAULT NULL,
  `og_type` varchar(100) DEFAULT NULL,
  `og_url` varchar(500) DEFAULT NULL,
  `summary` text DEFAULT NULL,
  `content` longtext DEFAULT NULL,
  `component_order` text DEFAULT NULL,
  `publish_start_at` datetime DEFAULT NULL,
  `publish_end_at` datetime DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_cms_pages_status` (`status`),
  KEY `idx_cms_pages_published_at` (`published_at`),
  KEY `idx_cms_pages_preview_token` (`preview_token`),
  KEY `idx_cms_pages_template_id` (`template_id`),
  KEY `idx_cms_pages_header_component` (`header_component_id`),
  KEY `idx_cms_pages_footer_component` (`footer_component_id`),
  KEY `idx_cms_pages_category_id` (`category_id`),
  CONSTRAINT `fk_cms_pages_category` FOREIGN KEY (`category_id`) REFERENCES `cms_categories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_cms_pages_footer_component` FOREIGN KEY (`footer_component_id`) REFERENCES `cms_components` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_cms_pages_header_component` FOREIGN KEY (`header_component_id`) REFERENCES `cms_components` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_cms_pages_template` FOREIGN KEY (`template_id`) REFERENCES `cms_templates` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `cms_pages`
--

LOCK TABLES `cms_pages` WRITE;
/*!40000 ALTER TABLE `cms_pages` DISABLE KEYS */;
INSERT INTO `cms_pages` VALUES
(1,'Home','home',NULL,NULL,1,2,3,'','','published','','','','','','','','','','','    <!-- Hero Section -->\n    <section class=\"hero\">\n        <div class=\"hero-content\">\n            <div class=\"hero-badge\">\n                <span class=\"hero-badge-dot\"></span>\n                Serving Your Area\n            </div>\n            <h1 class=\"hero-title\">\n                WE <span class=\"hero-title-accent\">FIX IT</span><br>FOR YOU\n            </h1>\n            <p class=\"hero-subtitle\">\n                Professional automotive repair services for every vehicle in your life. From mobile car repair to heavy-duty machinery — we\'ve got you covered.\n            </p>\n            <div class=\"hero-actions\">\n                <a href=\"#services\" class=\"btn btn-primary\">\n                    Explore Services\n                    <svg class=\"btn-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <path d=\"M5 12h14M12 5l7 7-7 7\"/>\n                    </svg>\n                </a>\n                <a href=\"#contact\" class=\"btn btn-secondary\">\n                    Get a Quote\n                </a>\n            </div>\n        </div>\n        <div class=\"scroll-indicator\">\n            <span>Scroll</span>\n            <div class=\"scroll-line\"></div>\n        </div>\n    </section>\n\n    <!-- Services Section -->\n    <section class=\"services\" id=\"services\">\n        <div class=\"section-header\">\n            <div class=\"section-label\">OUR SERVICES</div>\n            <h2 class=\"section-title\">COMPLETE AUTOMOTIVE<br>REPAIR SOLUTIONS</h2>\n        </div>\n        <div class=\"services-grid\">\n            <!-- Mobile Auto Service -->\n            <article class=\"service-card\">\n                <span class=\"mobile-badge\">Mobile Service</span>\n                <div class=\"service-icon\">\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <path d=\"M7 17m-2 0a2 2 0 1 0 4 0a2 2 0 1 0 -4 0\"/>\n                        <path d=\"M17 17m-2 0a2 2 0 1 0 4 0a2 2 0 1 0 -4 0\"/>\n                        <path d=\"M5 17h-2v-6l2-5h9l4 5h1a2 2 0 0 1 2 2v4h-2m-4 0h-6m-6 -6h15m-6 0v-5\"/>\n                    </svg>\n                </div>\n                <h3 class=\"service-title\">CARS & LIGHT VEHICLES</h3>\n                <p class=\"service-description\">\n                    We bring the shop to you. Our mobile mechanics service cars, light trucks, SUVs, and passenger vehicles at your home or workplace.\n                </p>\n                <div class=\"service-features\">\n                    <span class=\"service-feature\">Mobile Mechanic</span>\n                    <span class=\"service-feature\">On-Site Repair</span>\n                    <span class=\"service-feature\">Diagnostics</span>\n                </div>\n                <a href=\"vehicle-repair\" class=\"service-link\">\n                    Learn More\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <path d=\"M5 12h14M12 5l7 7-7 7\"/>\n                    </svg>\n                </a>\n            </article>\n\n            <!-- Marine Service -->\n            <article class=\"service-card\">\n                <div class=\"service-icon\">\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <path d=\"M2 20a2.4 2.4 0 0 0 2 1a2.4 2.4 0 0 0 2-1a2.4 2.4 0 0 1 2-1a2.4 2.4 0 0 1 2 1a2.4 2.4 0 0 0 2 1a2.4 2.4 0 0 0 2-1a2.4 2.4 0 0 1 2-1a2.4 2.4 0 0 1 2 1a2.4 2.4 0 0 0 2 1a2.4 2.4 0 0 0 2-1\"/>\n                        <path d=\"M4 18l-1-5h18l-1 5\"/>\n                        <path d=\"M5 13V7h4l4 6\"/>\n                        <path d=\"M9 7v6\"/>\n                    </svg>\n                </div>\n                <h3 class=\"service-title\">MARINE REPAIR</h3>\n                <p class=\"service-description\">\n                    Comprehensive marine engine repair and maintenance. Keep your boat running smooth with our expert technicians.\n                </p>\n                <div class=\"service-features\">\n                    <span class=\"service-feature\">Inboard/Outboard</span>\n                    <span class=\"service-feature\">Engine Repair</span>\n                    <span class=\"service-feature\">Winterization</span>\n                </div>\n                <a href=\"/marine\" class=\"service-link\">\n                    Learn More\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <path d=\"M5 12h14M12 5l7 7-7 7\"/>\n                    </svg>\n                </a>\n            </article>\n\n            <!-- RV Service -->\n            <article class=\"service-card\">\n                <div class=\"service-icon\">\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <path d=\"M5 17m-2 0a2 2 0 1 0 4 0a2 2 0 1 0 -4 0\"/>\n                        <path d=\"M17 17m-2 0a2 2 0 1 0 4 0a2 2 0 1 0 -4 0\"/>\n                        <path d=\"M3 17h-1v-11a1 1 0 0 1 1-1h9v12m-4 0h6\"/>\n                        <path d=\"M12 7h3l3 5h2a1 1 0 0 1 1 1v4h-2\"/>\n                        <path d=\"M6 10h4\"/>\n                    </svg>\n                </div>\n                <h3 class=\"service-title\">RV & MOTOR HOME</h3>\n                <p class=\"service-description\">\n                    Full-service RV and motor home repair. From engine work to living systems, we keep your home on wheels road-ready.\n                </p>\n                <div class=\"service-features\">\n                    <span class=\"service-feature\">Engine Service</span>\n                    <span class=\"service-feature\">Generator</span>\n                    <span class=\"service-feature\">Systems</span>\n                </div>\n                <a href=\"/rv\" class=\"service-link\">\n                    Learn More\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <path d=\"M5 12h14M12 5l7 7-7 7\"/>\n                    </svg>\n                </a>\n            </article>\n\n            <!-- Fleet Service -->\n            <article class=\"service-card\">\n                <div class=\"service-icon\">\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <path d=\"M8 7a4 4 0 1 0 8 0a4 4 0 0 0 -8 0\"/>\n                        <path d=\"M6 21v-2a4 4 0 0 1 4-4h.5\"/>\n                        <path d=\"M18 18m-3 0a3 3 0 1 0 6 0a3 3 0 1 0 -6 0\"/>\n                        <path d=\"M20.2 20.2l1.8 1.8\"/>\n                    </svg>\n                </div>\n                <h3 class=\"service-title\">FLEET SERVICES</h3>\n                <p class=\"service-description\">\n                    Dedicated fleet management and repair solutions. Minimize downtime and maximize efficiency for your business vehicles.\n                </p>\n                <div class=\"service-features\">\n                    <span class=\"service-feature\">Maintenance Plans</span>\n                    <span class=\"service-feature\">Priority Service</span>\n                    <span class=\"service-feature\">Reporting</span>\n                </div>\n                <a href=\"/fleet\" class=\"service-link\">\n                    Learn More\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <path d=\"M5 12h14M12 5l7 7-7 7\"/>\n                    </svg>\n                </a>\n            </article>\n\n            <!-- Heavy Duty Service -->\n            <article class=\"service-card\">\n                <div class=\"service-icon\">\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <path d=\"M5 17m-2 0a2 2 0 1 0 4 0a2 2 0 1 0 -4 0\"/>\n                        <path d=\"M17.5 17.5m-2.5 0a2.5 2.5 0 1 0 5 0a2.5 2.5 0 1 0 -5 0\"/>\n                        <path d=\"M3 17h-1v-4.5a2.5 2.5 0 0 1 2.5-2.5h9.5l4 4h2.5a2 2 0 0 1 2 2v1h-2\"/>\n                        <path d=\"M14 10v-4a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v4\"/>\n                        <path d=\"M7 17h8\"/>\n                    </svg>\n                </div>\n                <h3 class=\"service-title\">HEAVY DUTY</h3>\n                <p class=\"service-description\">\n                    Expert repair services for semi-trucks, commercial vehicles, and heavy equipment. Keeping your workhorses working.\n                </p>\n                <div class=\"service-features\">\n                    <span class=\"service-feature\">Diesel Engines</span>\n                    <span class=\"service-feature\">Transmission</span>\n                    <span class=\"service-feature\">DOT Inspection</span>\n                </div>\n                <a href=\"/heavy-duty\" class=\"service-link\">\n                    Learn More\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <path d=\"M5 12h14M12 5l7 7-7 7\"/>\n                    </svg>\n                </a>\n            </article>\n        </div>\n    </section>\n\n    <!-- CTA Section -->\n    <section class=\"cta\" id=\"contact\">\n        <div class=\"cta-inner\">\n            <h2 class=\"cta-title\">READY TO GET STARTED?</h2>\n            <p class=\"cta-subtitle\">\n                Contact us today for a free estimate. We\'re here to help keep you moving.\n            </p>\n            <div class=\"hero-actions\">\n                <a href=\"tel:+6164098940\" class=\"btn btn-primary\">\n                    <svg class=\"btn-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <path d=\"M5 4h4l2 5l-2.5 1.5a11 11 0 0 0 5 5l1.5-2.5l5 2v4a2 2 0 0 1-2 2a16 16 0 0 1-15-15a2 2 0 0 1 2-2\"/>\n                    </svg>\n                    (616) 409-8940\n                </a>\n                <a href=\"mailto:service@fixitfor.us\" class=\"btn btn-secondary\">\n                    <svg class=\"btn-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <path d=\"M3 7a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2h-14a2 2 0 0 1-2-2v-10z\"/>\n                        <path d=\"M3 7l9 6l9-6\"/>\n                    </svg>\n                    Email Us\n                </a>\n            </div>\n            <div class=\"cta-contact\">\n                <div class=\"contact-item\">\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <path d=\"M12 12m-3 0a3 3 0 1 0 6 0a3 3 0 1 0 -6 0\"/>\n                        <path d=\"M12 2a10 10 0 0 1 10 10c0 5.5-4.5 10-10 10s-10-4.5-10-10a10 10 0 0 1 10-10\"/>\n                    </svg>\n                    <span>Service Area: Metro &amp; Surrounding</span>\n                </div>\n                <div class=\"contact-item\">\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <path d=\"M12 12m-4 0a4 4 0 1 0 8 0a4 4 0 1 0 -8 0\"/>\n                        <path d=\"M2 12h4\"/>\n                        <path d=\"M18 12h4\"/>\n                    </svg>\n                    <span>Hours: Mon–Sat 7AM–6PM</span>\n                </div>\n            </div>\n        </div>\n    </section>','[]',NULL,NULL,'2026-02-28 09:03:47','2026-02-28 14:03:40','2026-03-07 23:12:16'),
(2,'RV Repair','rv-repair',NULL,NULL,1,2,3,'','','published','','','','','','','','','','','<!-- \n  FIXITFOR.US - RV & Motor Home Repair Page\n  WordPress Gutenberg Block Markup\n  \n  USAGE: Copy this entire content into a WordPress page using the Code Editor view\n  REQUIRES: The fixitforus-theme.css stylesheet to be enqueued in your theme\n-->\n\n<!-- wp:group {\"className\":\"ffu-page ffu-page--rv\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group ffu-page ffu-page--rv\">\n\n<!-- wp:group {\"className\":\"ffu-hero ffu-hero--rv\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group ffu-hero ffu-hero--rv\">\n\n<!-- wp:group {\"className\":\"ffu-hero-inner\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1400px\"}} -->\n<div class=\"wp-block-group ffu-hero-inner\">\n\n<!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-columns are-vertically-aligned-center\">\n\n<!-- wp:column {\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\">\n\n<!-- wp:html -->\n<span class=\"ffu-hero-badge ffu-hero-badge--rv\">\n    <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"1\" y=\"3\" width=\"15\" height=\"13\"/><polygon points=\"16 8 20 8 23 11 23 16 16 16 16 8\"/><circle cx=\"5.5\" cy=\"18.5\" r=\"2.5\"/><circle cx=\"18.5\" cy=\"18.5\" r=\"2.5\"/></svg>\n    RV Services\n</span>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":1,\"className\":\"ffu-hero-title\"} -->\n<h1 class=\"wp-block-heading ffu-hero-title\">RV & MOTOR HOME <span class=\"ffu-hero-title-accent ffu-hero-title-accent--rv\">REPAIR & MAINTENANCE</span></h1>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"className\":\"ffu-hero-description\"} -->\n<p class=\"ffu-hero-description\">Professional RV and motor home repair services. Mobile mechanics specializing in recreational vehicle maintenance, repairs, and pre-trip inspections. Get ready for your next adventure.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:html -->\n<div class=\"ffu-hero-features\">\n    <div class=\"ffu-hero-feature\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span>Mobile Service</span>\n    </div>\n    <div class=\"ffu-hero-feature\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span>All RV Types</span>\n    </div>\n    <div class=\"ffu-hero-feature\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>\n        <span>Pre-Trip Inspections</span>\n    </div>\n</div>\n<!-- /wp:html -->\n\n<!-- wp:buttons {\"className\":\"ffu-hero-actions\"} -->\n<div class=\"wp-block-buttons ffu-hero-actions\">\n\n<!-- wp:button {\"className\":\"ffu-btn ffu-btn-primary\"} -->\n<div class=\"wp-block-button ffu-btn ffu-btn-primary\"><a class=\"wp-block-button__link wp-element-button\" href=\"#quote\">Get Free Quote →</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"className\":\"ffu-btn ffu-btn-secondary\"} -->\n<div class=\"wp-block-button ffu-btn ffu-btn-secondary\"><a class=\"wp-block-button__link wp-element-button\" href=\"tel:+16164098940\">ߓ 616-409-8940</a></div>\n<!-- /wp:button -->\n\n</div>\n<!-- /wp:buttons -->\n\n</div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"className\":\"ffu-hero-visual\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center ffu-hero-visual\">\n\n<!-- wp:html -->\n<div class=\"ffu-hero-card ffu-hero-card--rv\">\n    <div class=\"ffu-hero-icon ffu-hero-icon--rv\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n            <rect x=\"1\" y=\"3\" width=\"15\" height=\"13\"/>\n            <polygon points=\"16 8 20 8 23 11 23 16 16 16 16 8\"/>\n            <circle cx=\"5.5\" cy=\"18.5\" r=\"2.5\"/>\n            <circle cx=\"18.5\" cy=\"18.5\" r=\"2.5\"/>\n        </svg>\n    </div>\n    <div class=\"ffu-hero-stats\">\n        <div class=\"ffu-stat\"><div class=\"ffu-stat-value ffu-stat-value--rv\">All</div><div class=\"ffu-stat-label\">RV Types</div></div>\n        <div class=\"ffu-stat\"><div class=\"ffu-stat-value ffu-stat-value--rv\">Mobile</div><div class=\"ffu-stat-label\">Service</div></div>\n        <div class=\"ffu-stat\"><div class=\"ffu-stat-value ffu-stat-value--rv\">24 Mo</div><div class=\"ffu-stat-label\">Warranty</div></div>\n    </div>\n</div>\n<!-- /wp:html -->\n\n</div>\n<!-- /wp:column -->\n\n</div>\n<!-- /wp:columns -->\n\n</div>\n<!-- /wp:group -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"ffu-section ffu-section--surface\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1400px\"}} -->\n<div class=\"wp-block-group ffu-section ffu-section--surface\">\n\n<!-- wp:group {\"className\":\"ffu-section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group ffu-section-header\">\n\n<!-- wp:html -->\n<div class=\"ffu-section-label\">OUR SERVICES</div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"className\":\"ffu-section-title\"} -->\n<h2 class=\"wp-block-heading has-text-align-center ffu-section-title\">RV MAINTENANCE & REPAIR</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"className\":\"ffu-section-subtitle\"} -->\n<p class=\"has-text-align-center ffu-section-subtitle\">Comprehensive RV services to keep your recreational vehicle road-ready.</p>\n<!-- /wp:paragraph -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:html -->\n<div class=\"ffu-services-grid\">\n    <div class=\"ffu-service-card\">\n        <div class=\"ffu-service-icon\">\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M12 2v4m0 12v4M2 12h4m12 0h4\"/></svg>\n        </div>\n        <h3 class=\"ffu-service-title\">ENGINE SERVICE</h3>\n        <p class=\"ffu-service-description\">Complete engine diagnostics, maintenance, and repair for gas and diesel RV engines.</p>\n    </div>\n    <div class=\"ffu-service-card\">\n        <div class=\"ffu-service-icon\">\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg>\n        </div>\n        <h3 class=\"ffu-service-title\">PRE-TRIP INSPECTIONS</h3>\n        <p class=\"ffu-service-description\">Comprehensive safety inspections before your trip to ensure worry-free travel.</p>\n    </div>\n    <div class=\"ffu-service-card\">\n        <div class=\"ffu-service-icon\">\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>\n        </div>\n        <h3 class=\"ffu-service-title\">BRAKE SERVICE</h3>\n        <p class=\"ffu-service-description\">Brake inspection, pad replacement, and complete brake system repairs.</p>\n    </div>\n    <div class=\"ffu-service-card\">\n        <div class=\"ffu-service-icon\">\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><rect x=\"3\" y=\"7\" width=\"18\" height=\"10\" rx=\"2\"/><path d=\"M7 7V5a2 2 0 0 1 2-2h6a2 2 0 0 1 2 2v2\"/><line x1=\"23\" y1=\"11\" x2=\"23\" y2=\"13\"/></svg>\n        </div>\n        <h3 class=\"ffu-service-title\">ELECTRICAL SYSTEMS</h3>\n        <p class=\"ffu-service-description\">12V and 120V electrical system diagnostics, wiring, and component repair.</p>\n    </div>\n    <div class=\"ffu-service-card\">\n        <div class=\"ffu-service-icon\">\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><path d=\"M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z\"/></svg>\n        </div>\n        <h3 class=\"ffu-service-title\">HVAC &amp; A/C</h3>\n        <p class=\"ffu-service-description\">Air conditioning, heating, and ventilation system service and repair.</p>\n    </div>\n    <div class=\"ffu-service-card\">\n        <div class=\"ffu-service-icon\">\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"><path d=\"M12 22V8\"/><path d=\"M5 12H2a10 10 0 0 0 20 0h-3\"/><circle cx=\"12\" cy=\"5\" r=\"3\"/></svg>\n        </div>\n        <h3 class=\"ffu-service-title\">SUSPENSION</h3>\n        <p class=\"ffu-service-description\">Leveling systems, air suspension, shocks, and chassis component service.</p>\n    </div>\n</div>\n<!-- /wp:html -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"className\":\"ffu-section\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"1400px\"}} -->\n<div class=\"wp-block-group ffu-section\">\n\n<!-- wp:group {\"className\":\"ffu-section-header\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group ffu-section-header\">\n\n<!-- wp:html -->\n<div class=\"ffu-section-label\">RV TYPES WE SERVICE</div>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"className\":\"ffu-section-title\"} -->\n<h2 class=\"wp-block-heading has-text-align-center ffu-section-title\">ALL RECREATIONAL VEHICLES</h2>\n<!-- /wp:heading -->\n\n</div>\n<!-- /wp:group -->\n\n<!-- wp:html -->\n<div class=\"ffu-benefits-grid\">\n    <div class=\"ffu-benefit-card\">\n        <div class=\"ffu-benefit-icon\">\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"1\" y=\"3\" width=\"15\" height=\"13\"/><polygon points=\"16 8 20 8 23 11 23 16 16 16 16 8\"/><circle cx=\"5.5\" 