(1,'component',2,'created','{\"id\":2,\"name\":\"Header\",\"slug\":\"header\",\"type\":\"header\",\"description\":\"main header\",\"content\":\"    <!-- Header -->\\n    <header class=\\\"header\\\">\\n        <div class=\\\"header-inner\\\">\\n            <a href=\\\"/\\\" class=\\\"logo\\\">\\n                <span class=\\\"logo-main\\\">FIXITFOR</span><span class=\\\"logo-accent\\\">.US</span>\\n            </a>\\n            <nav class=\\\"nav\\\" id=\\\"nav\\\">\\n                <a href=\\\"#services\\\" class=\\\"nav-link\\\">Services</a>\\n                <a href=\\\"#about\\\" class=\\\"nav-link\\\">About</a>\\n                <a href=\\\"#contact\\\" class=\\\"nav-link\\\">Contact</a>\\n                <a href=\\\"tel:+15551234567\\\" class=\\\"nav-cta\\\">Call Now</a>\\n            </nav>\\n            <button class=\\\"mobile-menu-btn\\\" id=\\\"menuBtn\\\" aria-label=\\\"Toggle menu\\\">\\n                <span></span>\\n                <span></span>\\n                <span></span>\\n            </button>\\n        </div>\\n    </header>\",\"css\":\"        :root {\\n            --color-bg: #0d0f12;\\n            --color-surface: #161a1f;\\n            --color-surface-elevated: #1e2328;\\n            --color-border: #2a2f36;\\n            --color-text: #f5f5f5;\\n            --color-text-muted: #9ca3af;\\n            --color-accent: #ff6b2c;\\n            --color-accent-glow: rgba(255, 107, 44, 0.3);\\n            --color-accent-hover: #ff8a57;\\n            --font-display: \'Bebas Neue\', sans-serif;\\n            --font-body: \'IBM Plex Sans\', sans-serif;\\n            --transition-smooth: cubic-bezier(0.4, 0, 0.2, 1);\\n        }\\n\\n        *, *::before, *::after {\\n            box-sizing: border-box;\\n            margin: 0;\\n            padding: 0;\\n        }\\n\\n        html {\\n            scroll-behavior: smooth;\\n        }\\n\\n        body {\\n            font-family: var(--font-body);\\n            background-color: var(--color-bg);\\n            color: var(--color-text);\\n            line-height: 1.6;\\n            overflow-x: hidden;\\n        }\\n\\n        /* Texture overlay */\\n        body::before {\\n            content: \'\';\\n            position: fixed;\\n            top: 0;\\n            left: 0;\\n            width: 100%;\\n            height: 100%;\\n            background-image: \\n                radial-gradient(ellipse at 20% 20%, rgba(255, 107, 44, 0.03) 0%, transparent 50%),\\n                radial-gradient(ellipse at 80% 80%, rgba(255, 107, 44, 0.02) 0%, transparent 50%);\\n            pointer-events: none;\\n            z-index: -1;\\n        }\\n\\n        /* Noise texture */\\n        body::after {\\n            content: \'\';\\n            position: fixed;\\n            top: 0;\\n            left: 0;\\n            width: 100%;\\n            height: 100%;\\n            background-image: url(\\\"data:image/svg+xml,%3Csvg viewBox=\'0 0 256 256\' xmlns=\'http://www.w3.org/2000/svg\'%3E%3Cfilter id=\'noise\'%3E%3CfeTurbulence type=\'fractalNoise\' baseFrequency=\'0.9\' numOctaves=\'4\' stitchTiles=\'stitch\'/%3E%3C/filter%3E%3Crect width=\'100%25\' height=\'100%25\' filter=\'url(%23noise)\'/%3E%3C/svg%3E\\\");\\n            opacity: 0.03;\\n            pointer-events: none;\\n            z-index: -1;\\n        }\\n\\n        a {\\n            color: inherit;\\n            text-decoration: none;\\n        }\\n\\n        /* Header */\\n        .header {\\n            position: fixed;\\n            top: 0;\\n            left: 0;\\n            right: 0;\\n            z-index: 100;\\n            padding: 1rem 2rem;\\n            background: rgba(13, 15, 18, 0.85);\\n            backdrop-filter: blur(20px);\\n            border-bottom: 1px solid var(--color-border);\\n            transition: all 0.3s var(--transition-smooth);\\n        }\\n\\n        .header-inner {\\n            max-width: 1400px;\\n            margin: 0 auto;\\n            display: flex;\\n            justify-content: space-between;\\n            align-items: center;\\n        }\\n\\n        .logo {\\n            font-family: var(--font-display);\\n            font-size: 1.75rem;\\n            letter-spacing: 0.05em;\\n            display: flex;\\n            align-items: baseline;\\n        }\\n\\n        .logo-main {\\n            color: var(--color-text);\\n        }\\n\\n        .logo-accent {\\n            color: var(--color-accent);\\n        }\\n\\n        .nav {\\n            display: flex;\\n            gap: 2rem;\\n            align-items: center;\\n        }\\n\\n        .nav-link {\\n            font-size: 0.875rem;\\n            font-weight: 500;\\n            color: var(--color-text-muted);\\n            transition: color 0.2s var(--transition-smooth);\\n            position: relative;\\n        }\\n\\n        .nav-link::after {\\n            content: \'\';\\n            position: absolute;\\n            bottom: -4px;\\n            left: 0;\\n            width: 0;\\n            height: 2px;\\n            background: var(--color-accent);\\n            transition: width 0.3s var(--transition-smooth);\\n        }\\n\\n        .nav-link:hover {\\n            color: var(--color-text);\\n        }\\n\\n        .nav-link:hover::after {\\n            width: 100%;\\n        }\\n\\n        .nav-cta {\\n            background: var(--color-accent);\\n            color: var(--color-bg);\\n            padding: 0.625rem 1.25rem;\\n            border-radius: 4px;\\n            font-weight: 600;\\n            font-size: 0.875rem;\\n            transition: all 0.2s var(--transition-smooth);\\n        }\\n\\n        .nav-cta:hover {\\n            background: var(--color-accent-hover);\\n            transform: translateY(-1px);\\n            box-shadow: 0 4px 20px var(--color-accent-glow);\\n        }\\n\\n        .mobile-menu-btn {\\n            display: none;\\n            flex-direction: column;\\n            gap: 5px;\\n            background: none;\\n            border: none;\\n            cursor: pointer;\\n            padding: 8px;\\n        }\\n\\n        .mobile-menu-btn span {\\n            display: block;\\n            width: 24px;\\n            height: 2px;\\n            background: var(--color-text);\\n            transition: all 0.3s var(--transition-smooth);\\n        }\\n\\n        /* Hero Section */\\n        .hero {\\n            min-height: 100vh;\\n            display: flex;\\n            align-items: center;\\n            justify-content: center;\\n            padding: 8rem 2rem 4rem;\\n            position: relative;\\n        }\\n\\n        .hero-content {\\n            max-width: 1000px;\\n            text-align: center;\\n        }\\n\\n        .hero-badge {\\n            display: inline-flex;\\n            align-items: center;\\n            gap: 0.5rem;\\n            background: var(--color-surface);\\n            border: 1px solid var(--color-border);\\n            padding: 0.5rem 1rem;\\n            border-radius: 50px;\\n            font-size: 0.8125rem;\\n            font-weight: 500;\\n            color: var(--color-text-muted);\\n            margin-bottom: 2rem;\\n            animation: fadeInDown 0.6s var(--transition-smooth);\\n        }\\n\\n        .hero-badge-dot {\\n            width: 8px;\\n            height: 8px;\\n            background: #22c55e;\\n            border-radius: 50%;\\n            animation: pulse 2s infinite;\\n        }\\n\\n        @keyframes pulse {\\n            0%, 100% { opacity: 1; }\\n            50% { opacity: 0.5; }\\n        }\\n\\n        .hero-title {\\n            font-family: var(--font-display);\\n            font-size: clamp(3.5rem, 10vw, 8rem);\\n            line-height: 0.95;\\n            letter-spacing: 0.02em;\\n            margin-bottom: 1.5rem;\\n            animation: fadeInUp 0.6s var(--transition-smooth) 0.1s both;\\n        }\\n\\n        .hero-title-accent {\\n            color: var(--color-accent);\\n            position: relative;\\n            display: inline-block;\\n        }\\n\\n        .hero-subtitle {\\n            font-size: clamp(1.125rem, 2.5vw, 1.375rem);\\n            color: var(--color-text-muted);\\n            max-width: 600px;\\n            margin: 0 auto 3rem;\\n            line-height: 1.7;\\n            animation: fadeInUp 0.6s var(--transition-smooth) 0.2s both;\\n        }\\n\\n        .hero-actions {\\n            display: flex;\\n            gap: 1rem;\\n            justify-content: center;\\n            flex-wrap: wrap;\\n            animation: fadeInUp 0.6s var(--transition-smooth) 0.3s both;\\n        }\\n\\n        .btn {\\n            display: inline-flex;\\n            align-items: center;\\n            gap: 0.5rem;\\n            padding: 1rem 2rem;\\n            border-radius: 4px;\\n            font-weight: 600;\\n            font-size: 0.9375rem;\\n            transition: all 0.2s var(--transition-smooth);\\n            cursor: pointer;\\n            border: none;\\n        }\\n\\n        .btn-primary {\\n            background: var(--color-accent);\\n            color: var(--color-bg);\\n        }\\n\\n        .btn-primary:hover {\\n            background: var(--color-accent-hover);\\n            transform: translateY(-2px);\\n            box-shadow: 0 8px 30px var(--color-accent-glow);\\n        }\\n\\n        .btn-secondary {\\n            background: transparent;\\n            color: var(--color-text);\\n            border: 1px solid var(--color-border);\\n        }\\n\\n        .btn-secondary:hover {\\n            border-color: var(--color-text-muted);\\n            background: var(--color-surface);\\n        }\\n\\n        .btn-icon {\\n            width: 18px;\\n            height: 18px;\\n        }\\n\\n        /* Scroll indicator */\\n        .scroll-indicator {\\n            position: absolute;\\n            bottom: 2rem;\\n            left: 50%;\\n            transform: translateX(-50%);\\n            display: flex;\\n            flex-direction: column;\\n            align-items: center;\\n            gap: 0.5rem;\\n            animation: fadeIn 1s var(--transition-smooth) 0.8s both;\\n        }\\n\\n        .scroll-indicator span {\\n            font-size: 0.75rem;\\n            color: var(--color-text-muted);\\n            text-transform: uppercase;\\n            letter-spacing: 0.1em;\\n        }\\n\\n        .scroll-line {\\n            width: 1px;\\n            height: 40px;\\n            background: linear-gradient(to bottom, var(--color-accent), transparent);\\n            animation: scrollBounce 2s infinite;\\n        }\\n\\n        @keyframes scrollBounce {\\n            0%, 100% { transform: scaleY(1); opacity: 1; }\\n            50% { transform: scaleY(0.5); opacity: 0.5; }\\n        }\\n\\n        /* Services Section */\\n        .services {\\n            padding: 6rem 2rem;\\n            position: relative;\\n        }\\n\\n        .section-header {\\n            max-width: 1400px;\\n            margin: 0 auto 4rem;\\n        }\\n\\n        .section-label {\\n            font-family: var(--font-display);\\n            font-size: 0.875rem;\\n            letter-spacing: 0.2em;\\n            color: var(--color-accent);\\n            margin-bottom: 1rem;\\n            display: flex;\\n            align-items: center;\\n            gap: 1rem;\\n        }\\n\\n        .section-label::before {\\n            content: \'\';\\n            width: 40px;\\n            height: 1px;\\n            background: var(--color-accent);\\n        }\\n\\n        .section-title {\\n            font-family: var(--font-display);\\n            font-size: clamp(2.5rem, 5vw, 4rem);\\n            letter-spacing: 0.02em;\\n            line-height: 1.1;\\n        }\\n\\n        .services-grid {\\n            max-width: 1400px;\\n            margin: 0 auto;\\n            display: grid;\\n            grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\\n            gap: 1.5rem;\\n        }\\n\\n        .service-card {\\n            background: var(--color-surface);\\n            border: 1px solid var(--color-border);\\n            border-radius: 8px;\\n            padding: 2rem;\\n            position: relative;\\n            overflow: hidden;\\n            transition: all 0.4s var(--transition-smooth);\\n            cursor: pointer;\\n        }\\n\\n        .service-card::before {\\n            content: \'\';\\n            position: absolute;\\n            top: 0;\\n            left: 0;\\n            right: 0;\\n            height: 3px;\\n            background: var(--color-accent);\\n            transform: scaleX(0);\\n            transform-origin: left;\\n            transition: transform 0.4s var(--transition-smooth);\\n        }\\n\\n        .service-card:hover {\\n            transform: translateY(-4px);\\n            border-color: var(--color-accent);\\n            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.3);\\n        }\\n\\n        .service-card:hover::before {\\n            transform: scaleX(1);\\n        }\\n\\n        .service-icon {\\n            width: 56px;\\n            height: 56px;\\n            background: var(--color-surface-elevated);\\n            border-radius: 8px;\\n            display: flex;\\n            align-items: center;\\n            justify-content: center;\\n            margin-bottom: 1.5rem;\\n            transition: all 0.3s var(--transition-smooth);\\n        }\\n\\n        .service-card:hover .service-icon {\\n            background: var(--color-accent);\\n        }\\n\\n        .service-icon svg {\\n            width: 28px;\\n            height: 28px;\\n            stroke: var(--color-accent);\\n            transition: stroke 0.3s var(--transition-smooth);\\n        }\\n\\n        .service-card:hover .service-icon svg {\\n            stroke: var(--color-bg);\\n        }\\n\\n        .service-title {\\n            font-family: var(--font-display);\\n            font-size: 1.5rem;\\n            letter-spacing: 0.03em;\\n            margin-bottom: 0.75rem;\\n        }\\n\\n        .service-description {\\n            color: var(--color-text-muted);\\n            font-size: 0.9375rem;\\n            margin-bottom: 1.5rem;\\n            line-height: 1.7;\\n        }\\n\\n        .service-features {\\n            display: flex;\\n            flex-wrap: wrap;\\n            gap: 0.5rem;\\n            margin-bottom: 1.5rem;\\n        }\\n\\n        .service-feature {\\n            font-size: 0.75rem;\\n            padding: 0.375rem 0.75rem;\\n            background: var(--color-surface-elevated);\\n            border-radius: 50px;\\n            color: var(--color-text-muted);\\n        }\\n\\n        .service-link {\\n            display: inline-flex;\\n            align-items: center;\\n            gap: 0.5rem;\\n            font-weight: 600;\\n            font-size: 0.875rem;\\n            color: var(--color-accent);\\n            transition: gap 0.3s var(--transition-smooth);\\n        }\\n\\n        .service-card:hover .service-link {\\n            gap: 0.75rem;\\n        }\\n\\n        .service-link svg {\\n            width: 16px;\\n            height: 16px;\\n        }\\n\\n        /* Mobile badge for car service */\\n        .mobile-badge {\\n            position: absolute;\\n            top: 1.5rem;\\n            right: 1.5rem;\\n            background: linear-gradient(135deg, #22c55e, #16a34a);\\n            color: white;\\n            font-size: 0.6875rem;\\n            font-weight: 600;\\n            padding: 0.375rem 0.75rem;\\n            border-radius: 50px;\\n            text-transform: uppercase;\\n            letter-spacing: 0.05em;\\n        }\\n\\n        /* CTA Section */\\n        .cta {\\n            padding: 6rem 2rem;\\n            background: var(--color-surface);\\n            border-top: 1px solid var(--color-border);\\n            border-bottom: 1px solid var(--color-border);\\n        }\\n\\n        .cta-inner {\\n            max-width: 800px;\\n            margin: 0 auto;\\n            text-align: center;\\n        }\\n\\n        .cta-title {\\n            font-family: var(--font-display);\\n            font-size: clamp(2rem, 4vw, 3rem);\\n            letter-spacing: 0.02em;\\n            margin-bottom: 1rem;\\n        }\\n\\n        .cta-subtitle {\\n            color: var(--color-text-muted);\\n            font-size: 1.125rem;\\n            margin-bottom: 2rem;\\n        }\\n\\n        .cta-contact {\\n            display: flex;\\n            flex-wrap: wrap;\\n            justify-content: center;\\n            gap: 2rem;\\n            margin-top: 2.5rem;\\n        }\\n\\n        .contact-item {\\n            display: flex;\\n            align-items: center;\\n            gap: 0.75rem;\\n            color: var(--color-text-muted);\\n        }\\n\\n        .contact-item svg {\\n            width: 20px;\\n            height: 20px;\\n            stroke: var(--color-accent);\\n        }\\n\\n        .contact-item a {\\n            color: var(--color-text);\\n            transition: color 0.2s var(--transition-smooth);\\n        }\\n\\n        .contact-item a:hover {\\n            color: var(--color-accent);\\n        }\\n\\n        /* Footer */\\n        .footer {\\n            background: var(--color-bg);\\n            padding: 4rem 2rem 2rem;\\n        }\\n\\n        .footer-inner {\\n            max-width: 1400px;\\n            margin: 0 auto;\\n        }\\n\\n        .footer-main {\\n            display: grid;\\n            grid-template-columns: 2fr repeat(3, 1fr);\\n            gap: 4rem;\\n            padding-bottom: 3rem;\\n            border-bottom: 1px solid var(--color-border);\\n        }\\n\\n        .footer-brand .logo {\\n            margin-bottom: 1rem;\\n        }\\n\\n        .footer-brand p {\\n            color: var(--color-text-muted);\\n            font-size: 0.9375rem;\\n            max-width: 300px;\\n            line-height: 1.7;\\n        }\\n\\n        .footer-social {\\n            display: flex;\\n            gap: 1rem;\\n            margin-top: 1.5rem;\\n        }\\n\\n        .social-link {\\n            width: 40px;\\n            height: 40px;\\n            background: var(--color-surface);\\n            border: 1px solid var(--color-border);\\n            border-radius: 8px;\\n            display: flex;\\n            align-items: center;\\n            justify-content: center;\\n            transition: all 0.2s var(--transition-smooth);\\n        }\\n\\n        .social-link:hover {\\n            background: var(--color-accent);\\n            border-color: var(--color-accent);\\n        }\\n\\n        .social-link svg {\\n            width: 18px;\\n            height: 18px;\\n            fill: var(--color-text-muted);\\n            transition: fill 0.2s var(--transition-smooth);\\n        }\\n\\n        .social-link:hover svg {\\n            fill: var(--color-bg);\\n        }\\n\\n        .footer-column h4 {\\n            font-family: var(--font-display);\\n            font-size: 1rem;\\n            letter-spacing: 0.1em;\\n            margin-bottom: 1.25rem;\\n            color: var(--color-text);\\n        }\\n\\n        .footer-column ul {\\n            list-style: none;\\n        }\\n\\n        .footer-column li {\\n            margin-bottom: 0.75rem;\\n        }\\n\\n        .footer-column a {\\n            color: var(--color-text-muted);\\n            font-size: 0.9375rem;\\n            transition: color 0.2s var(--transition-smooth);\\n        }\\n\\n        .footer-column a:hover {\\n            color: var(--color-accent);\\n        }\\n\\n        .footer-bottom {\\n            display: flex;\\n            justify-content: space-between;\\n            align-items: center;\\n            padding-top: 2rem;\\n            flex-wrap: wrap;\\n            gap: 1rem;\\n        }\\n\\n        .footer-copyright {\\n            color: var(--color-text-muted);\\n            font-size: 0.875rem;\\n        }\\n\\n        .footer-legal {\\n            display: flex;\\n            gap: 2rem;\\n        }\\n\\n        .footer-legal a {\\n            color: var(--color-text-muted);\\n            font-size: 0.875rem;\\n            transition: color 0.2s var(--transition-smooth);\\n        }\\n\\n        .footer-legal a:hover {\\n            color: var(--color-text);\\n        }\\n\\n        /* Animations */\\n        @keyframes fadeIn {\\n            from { opacity: 0; }\\n            to { opacity: 1; }\\n        }\\n\\n        @keyframes fadeInUp {\\n            from {\\n                opacity: 0;\\n                transform: translateY(20px);\\n            }\\n            to {\\n                opacity: 1;\\n                transform: translateY(0);\\n            }\\n        }\\n\\n        @keyframes fadeInDown {\\n            from {\\n                opacity: 0;\\n                transform: translateY(-20px);\\n            }\\n            to {\\n                opacity: 1;\\n                transform: translateY(0);\\n            }\\n        }\\n\\n        /* Mobile Styles */\\n        @media (max-width: 1024px) {\\n            .footer-main {\\n                grid-template-columns: 1fr 1fr;\\n                gap: 3rem;\\n            }\\n\\n            .footer-brand {\\n                grid-column: span 2;\\n            }\\n        }\\n\\n        @media (max-width: 768px) {\\n            .header {\\n                padding: 1rem;\\n            }\\n\\n            .nav {\\n                display: none;\\n                position: absolute;\\n                top: 100%;\\n                left: 0;\\n                right: 0;\\n                background: var(--color-surface);\\n                flex-direction: column;\\n                padding: 1.5rem;\\n                gap: 1rem;\\n                border-bottom: 1px solid var(--color-border);\\n            }\\n\\n            .nav.active {\\n                display: flex;\\n            }\\n\\n            .mobile-menu-btn {\\n                display: flex;\\n            }\\n\\n            .hero {\\n                padding: 7rem 1.5rem 4rem;\\n                min-height: auto;\\n            }\\n\\n            .hero-actions {\\n                flex-direction: column;\\n            }\\n\\n            .btn {\\n                width: 100%;\\n                justify-content: center;\\n            }\\n\\n            .scroll-indicator {\\n                display: none;\\n            }\\n\\n            .services {\\n                padding: 4rem 1.5rem;\\n            }\\n\\n            .services-grid {\\n                grid-template-columns: 1fr;\\n            }\\n\\n            .cta {\\n                padding: 4rem 1.5rem;\\n            }\\n\\n            .footer-main {\\n                grid-template-columns: 1fr;\\n                gap: 2rem;\\n            }\\n\\n            .footer-brand {\\n                grid-column: auto;\\n            }\\n\\n            .footer-bottom {\\n                flex-direction: column;\\n                text-align: center;\\n            }\\n\\n            .footer-legal {\\n                flex-wrap: wrap;\\n                justify-content: center;\\n            }\\n        }\",\"javascript\":\"\",\"css_assets\":\"\",\"js_assets\":\"\",\"is_active\":1,\"cache_ttl\":3600,\"created_by\":1,\"updated_by\":1,\"created_at\":\"2026-02-28 13:58:44\",\"updated_at\":\"2026-02-28 13:58:44\"}',1,'2026-02-28 13:58:44'),
(2,'component',3,'created','{\"id\":3,\"name\":\"Foot\",\"slug\":\"foot\",\"type\":\"footer\",\"description\":\"Default footer\",\"content\":\"    <!-- Footer -->\\n    <footer class=\\\"footer\\\">\\n        <div class=\\\"footer-inner\\\">\\n            <div class=\\\"footer-main\\\">\\n                <div class=\\\"footer-brand\\\">\\n                    <a href=\\\"/\\\" class=\\\"logo\\\">\\n                        <span class=\\\"logo-main\\\">FIXITFOR</span><span class=\\\"logo-accent\\\">.US</span>\\n                    </a>\\n                    <p>Professional automotive repair services you can trust. From mobile mechanics to heavy-duty solutions, we fix it for you.</p>\\n                    <div class=\\\"footer-social\\\">\\n                        <a href=\\\"#\\\" class=\\\"social-link\\\" aria-label=\\\"Facebook\\\">\\n                            <svg viewBox=\\\"0 0 24 24\\\">\\n                                <path d=\\\"M18 2h-3a5 5 0 0 0-5 5v3H7v4h3v8h4v-8h3l1-4h-4V7a1 1 0 0 1 1-1h3z\\\"/>\\n                            </svg>\\n                        </a>\\n                        <a href=\\\"#\\\" class=\\\"social-link\\\" aria-label=\\\"Instagram\\\">\\n                            <svg viewBox=\\\"0 0 24 24\\\">\\n                                <rect x=\\\"2\\\" y=\\\"2\\\" width=\\\"20\\\" height=\\\"20\\\" rx=\\\"5\\\" ry=\\\"5\\\"/>\\n                                <path d=\\\"M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z\\\"/>\\n                                <line x1=\\\"17.5\\\" y1=\\\"6.5\\\" x2=\\\"17.51\\\" y2=\\\"6.5\\\"/>\\n                            </svg>\\n                        </a>\\n                        <a href=\\\"#\\\" class=\\\"social-link\\\" aria-label=\\\"Twitter/X\\\">\\n                            <svg viewBox=\\\"0 0 24 24\\\">\\n                                <path d=\\\"M4 4l11.733 16h4.267l-11.733-16z\\\"/>\\n                                <path d=\\\"M4 20l6.768-6.768m2.46-2.46l6.772-6.772\\\"/>\\n                            </svg>\\n                        </a>\\n                        <a href=\\\"#\\\" class=\\\"social-link\\\" aria-label=\\\"YouTube\\\">\\n                            <svg viewBox=\\\"0 0 24 24\\\">\\n                                <path d=\\\"M22.54 6.42a2.78 2.78 0 0 0-1.94-2C18.88 4 12 4 12 4s-6.88 0-8.6.46a2.78 2.78 0 0 0-1.94 2A29 29 0 0 0 1 12a29 29 0 0 0 .46 5.58A2.78 2.78 0 0 0 3.4 19.6c1.72.46 8.6.46 8.6.46s6.88 0 8.6-.46a2.78 2.78 0 0 0 1.94-2A29 29 0 0 0 23 12a29 29 0 0 0-.46-5.58z\\\"/>\\n                                <polygon points=\\\"9.75 15.02 15.5 12 9.75 8.98 9.75 15.02\\\"/>\\n                            </svg>\\n                        </a>\\n                    </div>\\n                </div>\\n                <div class=\\\"footer-column\\\">\\n                    <h4>SERVICES</h4>\\n                    <ul>\\n                        <li><a href=\\\"/auto\\\">Mobile Auto Repair</a></li>\\n                        <li><a href=\\\"/marine\\\">Marine Services</a></li>\\n                        <li><a href=\\\"/rv\\\">RV & Motor Home</a></li>\\n                        <li><a href=\\\"/fleet\\\">Fleet Services</a></li>\\n                        <li><a href=\\\"/heavy-duty\\\">Heavy Duty</a></li>\\n                    </ul>\\n                </div>\\n                <div class=\\\"footer-column\\\">\\n                    <h4>COMPANY</h4>\\n                    <ul>\\n                        <li><a href=\\\"/about\\\">About Us</a></li>\\n                        <li><a href=\\\"/careers\\\">Careers</a></li>\\n                        <li><a href=\\\"/blog\\\">Blog</a></li>\\n                        <li><a href=\\\"/reviews\\\">Reviews</a></li>\\n                        <li><a href=\\\"/contact\\\">Contact</a></li>\\n                    </ul>\\n                </div>\\n                <div class=\\\"footer-column\\\">\\n                    <h4>SUPPORT</h4>\\n                    <ul>\\n                        <li><a href=\\\"/faq\\\">FAQ</a></li>\\n                        <li><a href=\\\"/warranty\\\">Warranty Info</a></li>\\n                        <li><a href=\\\"/schedule\\\">Schedule Service</a></li>\\n                        <li><a href=\\\"/financing\\\">Financing</a></li>\\n                        <li><a href=\\\"/emergency\\\">Emergency Service</a></li>\\n                    </ul>\\n                </div>\\n            </div>\\n            <div class=\\\"footer-bottom\\\">\\n                <p class=\\\"footer-copyright\\\">\\n                    &copy; 2025 Fixitforus Automotive LLC. All rights reserved.\\n                </p>\\n                <div class=\\\"footer-legal\\\">\\n                    <a href=\\\"/privacy\\\">Privacy Policy</a>\\n                    <a href=\\\"/terms\\\">Terms of Service</a>\\n                    <a href=\\\"/warranty\\\">Warranty</a>\\n                    <a href=\\\"/accessibility\\\">Accessibility</a>\\n                </div>\\n            </div>\\n        </div>\\n    </footer>\",\"css\":\"\",\"javascript\":\"        // Mobile menu toggle\\n        const menuBtn = document.getElementById(\'menuBtn\');\\n        const nav = document.getElementById(\'nav\');\\n\\n        menuBtn.addEventListener(\'click\', () => {\\n            nav.classList.toggle(\'active\');\\n            menuBtn.classList.toggle(\'active\');\\n        });\\n\\n        // Smooth scroll for anchor links\\n        document.querySelectorAll(\'a[href^=\\\"#\\\"]\').forEach(anchor => {\\n            anchor.addEventListener(\'click\', function (e) {\\n                e.preventDefault();\\n                const target = document.querySelector(this.getAttribute(\'href\'));\\n                if (target) {\\n                    target.scrollIntoView({\\n                        behavior: \'smooth\',\\n                        block: \'start\'\\n                    });\\n                    // Close mobile menu if open\\n                    nav.classList.remove(\'active\');\\n                }\\n            });\\n        });\\n\\n        // Header scroll effect\\n        let lastScroll = 0;\\n        window.addEventListener(\'scroll\', () => {\\n            const header = document.querySelector(\'.header\');\\n            const currentScroll = window.pageYOffset;\\n            \\n            if (currentScroll > 100) {\\n                header.style.padding = \'0.75rem 2rem\';\\n            } else {\\n                header.style.padding = \'1rem 2rem\';\\n            }\\n            \\n            lastScroll = currentScroll;\\n        });\\n\\n        // Intersection Observer for scroll animations\\n        const observerOptions = {\\n            threshold: 0.1,\\n            rootMargin: \'0px 0px -50px 0px\'\\n        };\\n\\n        const observer = new IntersectionObserver((entries) => {\\n            entries.forEach(entry => {\\n                if (entry.isIntersecting) {\\n                    entry.target.style.opacity = \'1\';\\n                    entry.target.style.transform = \'translateY(0)\';\\n                }\\n            });\\n        }, observerOptions);\\n\\n        // Animate service cards on scroll\\n        document.querySelectorAll(\'.service-card\').forEach((card, index) => {\\n            card.style.opacity = \'0\';\\n            card.style.transform = \'translateY(30px)\';\\n            card.style.transition = `all 0.6s cubic-bezier(0.4, 0, 0.2, 1) ${index * 0.1}s`;\\n            observer.observe(card);\\n        });\",\"css_assets\":\"\",\"js_assets\":\"\",\"is_active\":1,\"cache_ttl\":3600,\"created_by\":1,\"updated_by\":1,\"created_at\":\"2026-02-28 14:02:01\",\"updated_at\":\"2026-02-28 14:02:01\"}',1,'2026-02-28 14:02:01'),
(3,'page',1,'created','{\"id\":1,\"title\":\"Home\",\"slug\":\"home\",\"category_id\":null,\"template_id\":1,\"header_component_id\":2,\"footer_component_id\":3,\"custom_css\":\"\",\"custom_js\":\"\",\"status\":\"draft\",\"preview_token\":null,\"meta_title\":\"\",\"meta_description\":\"\",\"meta_keywords\":\"\",\"canonical_url\":\"\",\"og_title\":\"\",\"og_description\":\"\",\"og_image\":\"\",\"og_type\":\"\",\"og_url\":\"\",\"summary\":\"\",\"content\":\"    <!-- Hero Section -->\\n    <section class=\\\"hero\\\">\\n        <div class=\\\"hero-content\\\">\\n            <div class=\\\"hero-badge\\\">\\n                <span class=\\\"hero-badge-dot\\\"></span>\\n                Serving Your Area\\n            </div>\\n            <h1 class=\\\"hero-title\\\">\\n                WE <span class=\\\"hero-title-accent\\\">FIX IT</span><br>FOR YOU\\n            </h1>\\n            <p class=\\\"hero-subtitle\\\">\\n                Professional automotive repair services for every vehicle in your life. From mobile car repair to heavy-duty machinery — we\'ve got you covered.\\n            </p>\\n            <div class=\\\"hero-actions\\\">\\n                <a href=\\\"#services\\\" class=\\\"btn btn-primary\\\">\\n                    Explore Services\\n                    <svg class=\\\"btn-icon\\\" viewBox=\\\"0 0 24 24\\\" fill=\\\"none\\\" stroke=\\\"currentColor\\\" stroke-width=\\\"2\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\">\\n                        <path d=\\\"M5 12h14M12 5l7 7-7 7\\\"/>\\n                    </svg>\\n                </a>\\n                <a href=\\\"#contact\\\" class=\\\"btn btn-secondary\\\">\\n                    Get a Quote\\n                </a>\\n            </div>\\n        </div>\\n        <div class=\\\"scroll-indicator\\\">\\n            <span>Scroll</span>\\n            <div class=\\\"scroll-line\\\"></div>\\n        </div>\\n    </section>\\n\\n    <!-- Services Section -->\\n    <section class=\\\"services\\\" id