INSERT INTO `notification_templates` VALUES
(1,'workorder_parts_pending','Workorder Parts Pending','email','Parts Required for Workorder {workorder_number}','Hello {recipient_name},\n\nWorkorder {workorder_number} for {vehicle_info} is now waiting for parts.\n\nCustomer: {customer_name}\nVehicle: {vehicle_info}\n\nPlease review and order necessary parts.\n\nView workorder: {workorder_link}','2026-02-28 12:29:37','2026-02-28 12:29:37'),
(2,'workorder_parts_pending_manager','Workorder Parts Pending - Manager','email','Parts Pending Alert: {workorder_number}','Manager Alert: Workorder {workorder_number} is waiting for parts.\n\nCustomer: {customer_name}\nVehicle: {vehicle_info}\nTotal: ${grand_total}','2026-02-28 12:29:37','2026-02-28 12:29:37'),
(3,'workorder_in_progress','Workorder In Progress - Customer','email','Work Has Started on Your Vehicle - {workorder_number}','Hello {customer_name},\n\nGreat news! Work has begun on your {vehicle_info}.\n\nWorkorder: {workorder_number}\nTechnician: {technician_name}\n\nWe will notify you when the work is complete.\n\nThank you for your business!','2026-02-28 12:29:37','2026-02-28 12:29:37'),
(4,'workorder_on_hold','Workorder On Hold - Manager','email','Workorder {workorder_number} Placed On Hold','Alert: Workorder {workorder_number} has been placed on hold.\n\nCustomer: {customer_name}\nVehicle: {vehicle_info}\nPrevious Status: {from_status}\n\nPlease review and take action.','2026-02-28 12:29:37','2026-02-28 12:29:37'),
(5,'workorder_on_hold_tech','Workorder On Hold - Technician','email','Your Workorder {workorder_number} Is On Hold','Hello {technician_name},\n\nWorkorder {workorder_number} that you were assigned to has been placed on hold.\n\nVehicle: {vehicle_info}\nCustomer: {customer_name}','2026-02-28 12:29:37','2026-02-28 12:29:37'),
(6,'workorder_completed','Workorder Completed - Customer','email','Your Vehicle Service Is Complete - {workorder_number}','Hello {customer_name},\n\nThe service on your {vehicle_info} has been completed!\n\nWorkorder: {workorder_number}\nTotal: ${grand_total}\n\nPlease contact us to schedule pickup.\n\nThank you for choosing us!','2026-02-28 12:29:37','2026-02-28 12:29:37'),
(7,'workorder_completed_manager','Workorder Completed - Manager','email','Workorder Completed: {workorder_number}','Workorder {workorder_number} has been marked as complete.\n\nCustomer: {customer_name}\nVehicle: {vehicle_info}\nTotal: ${grand_total}','2026-02-28 12:29:37','2026-02-28 12:29:37'),
(8,'workorder_ready_pickup','Ready for Pickup - Customer Email','email','Your Vehicle Is Ready for Pickup! - {workorder_number}','Hello {customer_name},\n\nYour {vehicle_info} is ready for pickup!\n\nWorkorder: {workorder_number}\nTotal Due: ${grand_total}\n\nOur business hours are:\nMonday - Friday: 8:00 AM - 6:00 PM\nSaturday: 9:00 AM - 3:00 PM\n\nPlease bring a valid ID for vehicle release.\n\nThank you for your business!','2026-02-28 12:29:37','2026-02-28 12:29:37'),
(9,'workorder_ready_pickup_sms','Ready for Pickup - Customer SMS','sms','Vehicle Ready','Your {vehicle_info} is ready for pickup! Total: ${grand_total}. Workorder #{workorder_number}','2026-02-28 12:29:37','2026-02-28 12:29:37'),
(10,'workorder_awaiting_auth','Awaiting Authorization - Customer Email','email','Authorization Required for Additional Work - {workorder_number}','Hello {customer_name},\n\nDuring service on your {vehicle_info}, we discovered additional work that requires your authorization.\n\nWorkorder: {workorder_number}\nEstimated Additional Cost: ${grand_total}\n\nPlease review and approve the estimate to proceed.\n\nView and approve: {portal_link}','2026-02-28 12:29:37','2026-02-28 12:29:37'),
(11,'workorder_awaiting_auth_sms','Awaiting Authorization - Customer SMS','sms','Authorization Needed','Additional work needed on your {vehicle_info}. Please review estimate for Workorder #{workorder_number}. Total: ${grand_total}','2026-02-28 12:29:37','2026-02-28 12:29:37'),
(12,'workorder_cancelled','Workorder Cancelled - Customer','email','Workorder {workorder_number} Has Been Cancelled','Hello {customer_name},\n\nWorkorder {workorder_number} for your {vehicle_info} has been cancelled.\n\nIf you have any questions, please contact us.\n\nThank you.','2026-02-28 12:29:37','2026-02-28 12:29:37'),
(13,'workorder_cancelled_tech','Workorder Cancelled - Technician','email','Workorder {workorder_number} Cancelled','Hello {technician_name},\n\nWorkorder {workorder_number} that you were assigned to has been cancelled.\n\nVehicle: {vehicle_info}\nCustomer: {customer_name}','2026-02-28 12:29:37','2026-02-28 12:29:37'),
(14,'job_tracking_link','Job Tracking Link - Customer SMS','sms','Tracking Link','Hi {customer_name}, track your service for workorder {workorder_number} here: {job_tracking_link}','2026-02-28 12:29:37','2026-02-28 12:29:37');
/*!40000 ALTER TABLE `notification_templates` ENABLE KEYS */;
UNLOCK TABLES;

